using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Security.Cryptography;
using System.Web.Script.Serialization;
namespace ClearSpace {
public static class SoftwareUpdateTests {
 public static void Verify(string directory,Action<bool,string> check){
  string root=Path.Combine(directory,"software-update-fixtures");Directory.CreateDirectory(root);Func<Action,bool> rejects=action=>{try{action();return false;}catch{return true;}};
  check(new SoftwareRelease{Version="beta0.20",Build=2}.IsNewer("beta0.20",1),"An internal build update is detected within the same beta release");check(!new SoftwareRelease{Version="beta0.20",Build=1}.IsNewer("beta0.20",2),"Update checks reject older internal builds");check(new SoftwareRelease{Version="beta0.21",Build=1}.IsNewer("beta0.20",9),"A new beta release outranks the preceding internal build series");check(rejects(()=>SoftwareUpdates.VersionNumber("beta0.20/../evil")),"Release names cannot inject paths");
  check(new SoftwareRelease{Version="1.0",Build=1}.IsNewer("beta0.65535",65535)&&!new SoftwareRelease{Version="beta0.65535",Build=65535}.IsNewer("1.0",1),"Stable 1.0 outranks every supported Beta release without accepting a downgrade");
  check(new SoftwareRelease{Version="1.0",Build=2}.IsNewer("1.0",1)&&!new SoftwareRelease{Version="1.0",Build=1}.IsNewer("1.0",2),"Stable releases compare internal builds in both directions");
  check(new SoftwareRelease{Version="1.10",Build=1}.IsNewer("1.9",65535)&&new SoftwareRelease{Version="2.0",Build=1}.IsNewer("1.65535",65535),"Stable major and minor versions compare numerically without overflow");
  check(SoftwareUpdates.VersionNumber("1.0.0")==SoftwareUpdates.VersionNumber("1.0")&&!new SoftwareRelease{Version="1.0.0",Build=1}.IsNewer("1.0",1),"The historical 1.0 label compares as 1.0.0 without inventing a newer release");
  check(new SoftwareRelease{Version="1.0.10",Build=1}.IsNewer("1.0.2",65535)&&!new SoftwareRelease{Version="1.0.2",Build=65535}.IsNewer("1.0.10",1),"Three-part patch versions compare numerically and take priority over internal builds");
  check(new SoftwareRelease{Version="1.1.0",Build=1}.IsNewer("1.0.65535",65535)&&new SoftwareRelease{Version="2.0.0",Build=1}.IsNewer("1.65535.65535",65535),"Minor and major transitions take priority over every supported lower patch version");
  check(new SoftwareRelease{Version="1.0.0",Build=2}.IsNewer("1.0",1)&&!new SoftwareRelease{Version="1.0",Build=1}.IsNewer("1.0.0",2),"Internal builds compare consistently across two-part and three-part labels");
  check(new SoftwareRelease{Version="1.0.0",Build=1}.IsNewer("beta0.65535",65535)&&SoftwareUpdates.VersionNumber("65535.65535.65535")==281474976710655L,"Three-part stable versions follow Beta releases without overflowing the version key");
  foreach(string invalid in new[]{"1.0/../evil","1.0\n","01.0","1.00","0.20","65536.0","1.65536","1.0.0.0","1.0.0/../evil","1.0.0\n","1.0.00","1.0.65536","1.0.-1","beta0.20\n"})check(rejects(()=>SoftwareUpdates.VersionNumber(invalid)),"Malformed or out-of-range release version is rejected: "+invalid.Replace("\n","\\n"));
  check(!SoftwareUpdates.TrustedDownload(new Uri("http://github.com/CrazyHandin/Clarity"))&&!SoftwareUpdates.TrustedDownload(new Uri("https://github.com.attacker.invalid/a"))&&!SoftwareUpdates.TrustedDownload(new Uri("https://user@github.com/a")),"Software downloads reject HTTP, lookalike hosts, and embedded credentials");
  using(var stop=new System.Threading.CancellationTokenSource()){stop.Cancel();var cancelled=new SoftwareAsset{Name="cancelled.zip",Url=SoftwareUpdates.AssetUrl("beta0.20","cancelled.zip"),SHA256=new string('a',64),Size=10};check(rejects(()=>SoftwareUpdates.Download(cancelled,root,stop.Token,null))&&!File.Exists(Path.Combine(root,"cancelled.zip")),"Cancelling before download makes no network request and removes its partial file");}
  var published=new List<Dictionary<string,object>>();var artifacts=new List<Dictionary<string,object>>();foreach(string suffix in new[]{"-setup.exe","-portable.zip"}){string name="Clarity-beta0.20-build2"+suffix,hash=new string('a',64);published.Add(new Dictionary<string,object>{{"name",name},{"size",10L},{"digest","sha256:"+hash},{"browser_download_url",SoftwareUpdates.AssetUrl("beta0.20",name)}});artifacts.Add(new Dictionary<string,object>{{"Name",name},{"Size",10L},{"SHA256",hash}});}
  var manifest=new Dictionary<string,object>{{"Schema",1},{"Version","beta0.20"},{"Build",2},{"Artifacts",artifacts}};var json=new JavaScriptSerializer();check(SoftwareUpdates.ParseManifest(json.Serialize(manifest),"beta0.20",published,"").Assets.Count==2,"A build manifest must match both published GitHub package records");published[0]["digest"]="sha256:"+new string('b',64);check(rejects(()=>SoftwareUpdates.ParseManifest(json.Serialize(manifest),"beta0.20",published,"")),"A package hash mismatch prevents update selection");published[0]["digest"]="sha256:"+new string('a',64);published[0]["browser_download_url"]="https://example.invalid/payload.exe";check(rejects(()=>SoftwareUpdates.ParseManifest(json.Serialize(manifest),"beta0.20",published,"")),"Manifest downloads stay within the configured repository");
  manifest["Highlights"]=new Dictionary<string,object>{{"zh-CN","Fixture summary"},{"en","Fixture summary"}};int requests=0;using(var rsa=new RSACryptoServiceProvider(3072,new CspParameters{ProviderType=24,Flags=CspProviderFlags.CreateEphemeralKey})){rsa.PersistKeyInCsp=false;string signed=UpdateServiceTests.Sign(json.Serialize(manifest),rsa);var direct=SoftwareUpdates.Check(System.Threading.CancellationToken.None,(url,limit,token)=>{System.Threading.Interlocked.Increment(ref requests);if(url!=SoftwareUpdates.DirectManifestUrl||url.Contains("api.github.com")||limit!=65536)throw new IOException("Unexpected API dependency");return signed;},rsa.ToXmlString(false));check(requests==1&&direct.Build==2&&direct.Notes=="Fixture summary"&&direct.Assets.All(a=>a.Url.StartsWith("https://github.com/CrazyHandin/Clarity/releases/download/")),"Update checks verify a signed official HTTPS manifest without depending on anonymous API limits");UpdateChecksTests.Verify(signed,rsa.ToXmlString(false),check);}
  UpdateServiceTests.Verify(root,check);
  UpdateStrategyTests.Verify(root,check);
  artifacts[0]["SHA256"]="invalid";check(rejects(()=>SoftwareUpdates.ParseDownloadManifest(json.Serialize(manifest))),"Direct manifest checks still reject malformed package checksums");artifacts[0]["SHA256"]=new string('a',64);artifacts[0]["Name"]="../Clarity.exe";check(rejects(()=>SoftwareUpdates.ParseDownloadManifest(json.Serialize(manifest))),"Direct update manifests cannot redirect packages through arbitrary paths");artifacts[0]["Name"]="Clarity-beta0.20-build2-setup.exe";
  var stableArtifacts=new[]{"-setup.exe","-portable.zip"}.Select(suffix=>new Dictionary<string,object>{{"Name","Clarity-1.0-build1"+suffix},{"Size",10L},{"SHA256",new string('a',64)}}).ToArray();var stableManifest=new Dictionary<string,object>{{"Schema",1},{"Version","1.0"},{"Build",1},{"Artifacts",stableArtifacts}};var stableRelease=SoftwareUpdates.ParseDownloadManifest(json.Serialize(stableManifest));check(stableRelease.Version=="1.0"&&stableRelease.Assets.Count==2&&stableRelease.Assets.All(a=>a.Url.StartsWith("https://github.com/CrazyHandin/Clarity/releases/download/1.0/")),"Stable update manifests select only the matching official 1.0 packages");
  stableManifest["Version"]="1.0.0";foreach(var artifact in stableArtifacts)artifact["Name"]=((string)artifact["Name"]).Replace("Clarity-1.0-","Clarity-1.0.0-");var threePart=SoftwareUpdates.ParseDownloadManifest(json.Serialize(stableManifest));check(threePart.Version=="1.0.0"&&threePart.Assets.All(a=>a.Url.StartsWith("https://github.com/CrazyHandin/Clarity/releases/download/1.0.0/Clarity-1.0.0-build1-")),"Three-part manifests retain exact release tags and matching package names");stableArtifacts[0]["Name"]="Clarity-1.0-build1-setup.exe";check(rejects(()=>SoftwareUpdates.ParseDownloadManifest(json.Serialize(stableManifest))),"A three-part manifest cannot select a package from the old two-part release");
  var plainArtifacts=new[]{"-setup.exe","-portable.zip"}.Select(suffix=>new Dictionary<string,object>{{"Name","Clarity-1.0.6"+suffix},{"Size",10L},{"SHA256",new string('a',64)}}).ToArray();var plainManifest=new Dictionary<string,object>{{"Schema",1},{"Version","1.0.6"},{"Build",3},{"Artifacts",plainArtifacts}};var plainRelease=SoftwareUpdates.ParseDownloadManifest(json.Serialize(plainManifest));check(plainRelease.Build==3&&plainRelease.Assets.Count==2&&plainRelease.Assets.All(a=>!a.Name.Contains("build")&&a.Url.Contains("/1.0.6/")),"Version-only package names preserve internal build comparison and official download paths");
  plainArtifacts[1]["Name"]="Clarity-1.0.6-build3-portable.zip";check(rejects(()=>SoftwareUpdates.ParseDownloadManifest(json.Serialize(plainManifest))),"A manifest cannot mix legacy and new naming schemes");plainArtifacts[0]["Name"]="Clarity-1.0.6-build3-setup.exe";check(SoftwareUpdates.ParseDownloadManifest(json.Serialize(plainManifest)).Assets.Count==2,"Legacy build-tagged package names remain supported");plainArtifacts[0]["Name"]="Clarity-1.0.6-build2-setup.exe";check(rejects(()=>SoftwareUpdates.ParseDownloadManifest(json.Serialize(plainManifest))),"A manifest cannot select legacy packages with the wrong internal build");
  foreach(string name in new[]{"../outside.txt","/Clarity.exe","docs/../Clarity.exe","docs\\TERMS.txt","Logs/history.json","personal.txt"})check(rejects(()=>UpdatePackage.Destination(root,name)),"Portable update path is rejected: "+name);
  string newCache=Path.Combine(root,"first-run","SoftwareUpdates"),session=UpdateLauncher.NewSessionAt(newCache);check(Directory.Exists(session)&&Path.GetDirectoryName(session)==newCache,"First update creates its absent cache parents before establishing a private session");
  string zip=Path.Combine(root,"valid.zip");using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create)){foreach(string name in new[]{"Clarity.exe","Clarity.exe.config","README.md","docs/TERMS.txt","rules/Winapp2.ini"})using(var writer=new StreamWriter(archive.CreateEntry(name).Open()))writer.Write("new "+name);}string payload=Path.Combine(root,"payload");var files=UpdatePackage.Extract(zip,SoftwareUpdates.HashFile(zip),payload);check(files.Count==5&&File.Exists(Path.Combine(payload,"docs","TERMS.txt"))&&File.Exists(Path.Combine(payload,"rules","Winapp2.ini")),"Verified archives safely create previously absent nested docs and rules directories");check(rejects(()=>UpdatePackage.Extract(zip,new string('0',64),Path.Combine(root,"bad-hash"))),"Portable application rejects an archive modified after downloading");
  var lockedAsset=new SoftwareAsset{Name=Path.GetFileName(zip),Size=new FileInfo(zip).Length,SHA256=SoftwareUpdates.HashFile(zip)};using(var locked=UpdateLauncher.OpenPackage(zip,lockedAsset)){check(rejects(()=>File.AppendAllText(zip,"tampered"))&&rejects(()=>File.Delete(zip)),"A verified package stays read-locked against modification and deletion while preparing launch");}
  string missingRules=Path.Combine(root,"missing-rules.zip");using(var archive=ZipFile.Open(missingRules,ZipArchiveMode.Create))foreach(string name in new[]{"Clarity.exe","Clarity.exe.config"})using(var writer=new StreamWriter(archive.CreateEntry(name).Open()))writer.Write("incomplete package");check(rejects(()=>UpdatePackage.Extract(missingRules,SoftwareUpdates.HashFile(missingRules),Path.Combine(root,"missing-rules"))),"An update missing its bundled rule file is rejected before program replacement");
  string target=Path.Combine(root,"target");Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(target,"Clarity.exe"),"old program");File.WriteAllText(Path.Combine(target,"README.md"),"old readme");Directory.CreateDirectory(Path.Combine(target,"Logs"));File.WriteAllText(Path.Combine(target,"Logs","keep.json"),"personal audit fixture");
  string nested=Path.Combine(payload,"docs","TERMS.txt");byte[] correct=File.ReadAllBytes(nested);File.AppendAllText(nested,"tampered after extraction");check(rejects(()=>UpdatePackage.Apply(target,files))&&File.ReadAllText(Path.Combine(target,"Clarity.exe"))=="old program","Tampering with extracted content aborts replacement and restores already replaced program files");File.WriteAllBytes(nested,correct);
  check(rejects(()=>UpdatePackage.Apply(target,files,index=>{if(index==1)throw new IOException("injected update failure");})),"An interrupted program replacement reports failure");check(File.ReadAllText(Path.Combine(target,"Clarity.exe"))=="old program"&&!File.Exists(Path.Combine(target,"Clarity.exe.config")),"Failed portable replacement rolls back the original executable and new files");UpdatePackage.Apply(target,files);check(File.ReadAllText(Path.Combine(target,"Clarity.exe"))=="new Clarity.exe"&&File.ReadAllText(Path.Combine(target,"README.md"))=="new README.md"&&File.ReadAllText(Path.Combine(target,"docs","TERMS.txt"))=="new docs/TERMS.txt","A complete portable transaction replaces its program and nested document payload");check(File.ReadAllText(Path.Combine(target,"Logs","keep.json"))=="personal audit fixture","Program updates preserve cleanup history and other unlisted user files");
  string escape=Path.Combine(root,"escape.zip");using(var archive=ZipFile.Open(escape,ZipArchiveMode.Create))using(var writer=new StreamWriter(archive.CreateEntry("../outside.txt").Open()))writer.Write("never extract");check(rejects(()=>UpdatePackage.Extract(escape,SoftwareUpdates.HashFile(escape),Path.Combine(root,"escape")))&&!File.Exists(Path.Combine(root,"outside.txt")),"Traversal inside a downloaded ZIP cannot write outside its extraction root");
  string badPlan=Path.Combine(root,"plan.dat");File.WriteAllText(badPlan,"not an update plan");check(UpdateLauncher.Apply(badPlan)==1&&!File.Exists(Path.Combine(root,"error.txt")),"An untrusted update task cannot write into an arbitrary directory");
  string previous=CleaningHistory.LastDirectory;try{string log=CleaningHistory.Save(new CleanResult{Deleted=1},Path.Combine(root,"portable-app"));check(File.Exists(log)&&Path.GetDirectoryName(log)==Path.Combine(root,"portable-app","Logs"),"Cleanup history automatically saves underneath the program directory");}finally{CleaningHistory.LastDirectory=previous;}
 }
}
